window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e2f68ffcfc61a6ee"]={"versions": [{"id": "FIG-e2f68ffcfc61a6ee", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des internen Ablaufs des Rechenschritts „Compute CRC“ im AUTOSAR E2E Profile 4 (Classic und Adaptive Platform). Das Diagramm spezifiziert den Algorithmus zur Prüfsummenberechnung innerhalb der Protokollfunktionen <code>E2E_P04Protect()</code> und <code>E2E_P04Check()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Funktionskontexte</strong>: <code>E2E_P04Protect()</code>, <code>E2E_P04Check()</code>.\n</li><li><strong>Eingangsdaten &amp; Parameter</strong>: <code>Data</code> (Byte-Array der Daten), <code>Offset</code> (Position des E2E-Headers im Datenstrom), <code>Length</code> (Gesamtlänge der Daten).\n</li><li><strong>Berechnungsfunktion &amp; Signatur</strong>: <code>Crc_CalculateCRC32P4(Crc_DataPtr, Crc_Length, Crc_StartValue32, Crc_IsFirstCall)</code>.\n</li><li><strong>Variablen</strong>: <code>uint32 ComputedCRC</code>.\n</li><li><strong>Kommentar-Notizen</strong>:\n<ul class=\"fig-list\"><li>Erster Schritt: Berechnung über die Bytes vor dem CRC-Feld (Länge: <code>Offset + 8</code>).\n</li><li>Zweiter Schritt: Berechnung über nachfolgende Bytes nach dem CRC-Feld (<code>Offset + 12</code>), sofern vorhanden.\n</li><li>Finaler Zustand: <code>ComputedCRC</code> über den gesamten geschützten Bereich.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Start</strong>: Initialer Startknoten leitet in die erste CRC-Berechnung ein.\n</li><li><strong>Erster CRC-Abschnitt</strong>: Aufruf von <code>uint32 ComputedCRC = Crc_CalculateCRC32P4(Crc_DataPtr: &amp;Data[0], Crc_Length: Offset+8, Crc_StartValue32: 0xFF&#x27;FF&#x27;FF&#x27;FF, Crc_IsFirstCall: TRUE)</code>.\n</li><li><strong>Entscheidungsraute</strong>: Prüfung der Guard-Bedingung <code>Offset + 12 &lt; Length</code>.\n<ul class=\"fig-list\"><li><code>[true]</code>: Aufruf von <code>ComputedCRC = Crc_CalculateCRC32P4(Crc_DataPtr: &amp;Data[offset+12], Crc_Length: Length-Offset-12, Crc_StartValue32: ComputedCRC, Crc_IsFirstCall: FALSE)</code>.\n</li><li><code>[false]</code>: Umgehung der zweiten CRC-Berechnung direkt zum Zusammenführungsknoten.\n</li></ul>\n</li><li><strong>Merge &amp; Ende</strong>: Die Pfade vereinigen sich in einer Zusammenführungsraute und münden im Endknoten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe gemäß <code>[PRS_E2E_00367]</code> für die Berechnung des 32-Bit-CRC (Profile 4). Der CRC-Wert wird in zwei Teilen berechnet, um das CRC-Feld selbst (4 Bytes ab <code>Offset + 8</code> bis <code>Offset + 12</code>) auszulassen. Falls die Daten exakt mit dem CRC enden (<code>Offset + 12 == Length</code>), entfällt der zweite Funktionsaufruf. Die Initialisierung erfolgt mit dem Startwert <code>0xFFFFFFFF</code> und <code>Crc_IsFirstCall = TRUE</code>.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-6d8e2393bb985fc3", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des internen Ablaufs des Rechenschritts „Compute CRC“ im AUTOSAR E2E Profile 4 (Classic und Adaptive Platform). Das Diagramm spezifiziert den Algorithmus zur Prüfsummenberechnung innerhalb der Protokollfunktionen <code>E2E_P04Protect()</code>, <code>E2E_P04Check()</code> und <code>E2E_P04Forward()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Funktionskontexte</strong>: <code>E2E_P04Protect()</code>, <code>E2E_P04Check()</code>, <code>E2E_P04Forward()</code>.\n</li><li><strong>Eingangsdaten &amp; Parameter</strong>: <code>Data</code> (Byte-Array der Daten), <code>Offset</code> (Position des E2E-Headers im Datenstrom), <code>Length</code> (Gesamtlänge der Daten).\n</li><li><strong>Berechnungsfunktion &amp; Signatur</strong>: <code>Crc_CalculateCRC32P4(Crc_DataPtr, Crc_Length, Crc_StartValue32, Crc_IsFirstCall)</code>.\n</li><li><strong>Variablen</strong>: <code>uint32 ComputedCRC</code>.\n</li><li><strong>Kommentar-Notizen</strong>:\n<ul class=\"fig-list\"><li>Erster Schritt: Berechnung über die Bytes vor dem CRC-Feld (Länge: <code>Offset + 8</code>).\n</li><li>Zweiter Schritt: Berechnung über nachfolgende Bytes nach dem CRC-Feld (<code>Offset + 12</code>), sofern vorhanden.\n</li><li>Finaler Zustand: <code>ComputedCRC</code> über den gesamten geschützten Bereich.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Start</strong>: Initialer Startknoten leitet in die erste CRC-Berechnung ein.\n</li><li><strong>Erster CRC-Abschnitt</strong>: Aufruf von <code>uint32 ComputedCRC = Crc_CalculateCRC32P4(Crc_DataPtr: &amp;Data[0], Crc_Length: Offset+8, Crc_StartValue32: 0xFF&#x27;FF&#x27;FF&#x27;FF, Crc_IsFirstCall: TRUE)</code>.\n</li><li><strong>Entscheidungsraute</strong>: Prüfung der Guard-Bedingung <code>Offset + 12 &lt; Length</code>.\n<ul class=\"fig-list\"><li><code>[true]</code>: Aufruf von <code>ComputedCRC = Crc_CalculateCRC32P4(Crc_DataPtr: &amp;Data[offset+12], Crc_Length: Length-Offset-12, Crc_StartValue32: ComputedCRC, Crc_IsFirstCall: FALSE)</code>.\n</li><li><code>[false]</code>: Umgehung der zweiten CRC-Berechnung direkt zum Zusammenführungsknoten.\n</li></ul>\n</li><li><strong>Merge &amp; Ende</strong>: Die Pfade vereinigen sich in einer Zusammenführungsraute und münden im Endknoten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für die Berechnung des 32-Bit-CRC (Profile 4) in den Schutz-, Prüf- und Weiterleitungsfunktionen (<code>E2E_P04Protect</code>, <code>E2E_P04Check</code>, <code>E2E_P04Forward</code>). Der CRC-Wert wird in zwei Schritten berechnet, um das CRC-Feld selbst (4 Bytes ab <code>Offset + 8</code> bis <code>Offset + 12</code>) zu überspringen. Falls keine Daten hinter dem CRC-Feld existieren (<code>Offset + 12 == Length</code>), entfällt der zweite Rechenschritt. Die Initialisierung erfolgt mit Startwert <code>0xFFFFFFFF</code> und <code>Crc_IsFirstCall = TRUE</code>.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c131f325abf760b6", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des internen Ablaufs des Rechenschritts „Compute CRC“ im AUTOSAR E2E Profile 4 (Classic und Adaptive Platform). Das Diagramm spezifiziert den Algorithmus zur Prüfsummenberechnung innerhalb der Protokollfunktionen <code>E2E_P04Protect()</code>, <code>E2E_P04Check()</code> und <code>E2E_P04Forward()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Funktionskontexte</strong>: <code>E2E_P04Protect()</code>, <code>E2E_P04Check()</code>, <code>E2E_P04Forward()</code>.\n</li><li><strong>Eingangsdaten &amp; Parameter</strong>: <code>Data</code> (Byte-Array der Daten), <code>Offset</code> (Position des E2E-Headers im Datenstrom), <code>Length</code> (Gesamtlänge der Daten).\n</li><li><strong>Berechnungsfunktion &amp; Signatur</strong>: <code>Crc_CalculateCRC32P4(Crc_DataPtr, Crc_Length, Crc_StartValue32, Crc_IsFirstCall)</code>.\n</li><li><strong>Variablen</strong>: <code>uint32 ComputedCRC</code>.\n</li><li><strong>Kommentar-Notizen</strong>:\n<ul class=\"fig-list\"><li>Erster Schritt: Berechnung über die Bytes vor dem CRC-Feld (Länge: <code>Offset + 8</code>).\n</li><li>Zweiter Schritt: Berechnung über nachfolgende Bytes nach dem CRC-Feld (<code>Offset + 12</code>), sofern vorhanden.\n</li><li>Finaler Zustand: <code>ComputedCRC</code> über den gesamten geschützten Bereich.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Start</strong>: Initialer Startknoten leitet in die erste CRC-Berechnung ein.\n</li><li><strong>Erster CRC-Abschnitt</strong>: Aufruf von <code>uint32 ComputedCRC = Crc_CalculateCRC32P4(Crc_DataPtr: &amp;Data[0], Crc_Length: Offset+8, Crc_StartValue32: 0xFF&#x27;FF&#x27;FF&#x27;FF, Crc_IsFirstCall: TRUE)</code>.\n</li><li><strong>Entscheidungsraute</strong>: Prüfung der Guard-Bedingung <code>Offset + 12 &lt; Length</code>.\n<ul class=\"fig-list\"><li><code>[true]</code>: Aufruf von <code>ComputedCRC = Crc_CalculateCRC32P4(Crc_DataPtr: &amp;Data[offset+12], Crc_Length: Length-Offset-12, Crc_StartValue32: ComputedCRC, Crc_IsFirstCall: FALSE)</code>.\n</li><li><code>[false]</code>: Umgehung der zweiten CRC-Berechnung direkt zum Zusammenführungsknoten.\n</li></ul>\n</li><li><strong>Merge &amp; Ende</strong>: Die Pfade vereinigen sich in einer Zusammenführungsraute und münden im Endknoten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für die Berechnung des 32-Bit-CRC (Profile 4) in den Schutz-, Prüf- und Weiterleitungsfunktionen (<code>E2E_P04Protect</code>, <code>E2E_P04Check</code>, <code>E2E_P04Forward</code>). Der CRC-Wert wird in zwei Schritten berechnet, um das CRC-Feld selbst (4 Bytes ab <code>Offset + 8</code> bis <code>Offset + 12</code>) zu überspringen. Falls keine Daten hinter dem CRC-Feld existieren (<code>Offset + 12 == Length</code>), entfällt der zweite Rechenschritt. Die Initialisierung erfolgt mit Startwert <code>0xFFFFFFFF</code> und <code>Crc_IsFirstCall = TRUE</code>.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-e2f68ffcfc61a6ee", "to": "FIG-6d8e2393bb985fc3", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Funktionszuordnung oben links: Ergänzung des Funktionsbausteins <code>E2E_P04Forward()</code> neben den bestehenden Elementen <code>E2E_P04Protect()</code> und <code>E2E_P04Check()</code>.\n</li></ul>"}, {"from": "FIG-6d8e2393bb985fc3", "to": "FIG-c131f325abf760b6", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
